282	    @Override
283	    @Transactional
284	    public ServiceResult submitTiming(String raceId, String bib, SubmitTimingRequest request) {
285	        return withIdempotency(request.requestId(), "SUBMIT_TIMING",
286	                orderedParams(
287	                        "raceId", raceId,
288	                        "bib", bib,
289	                        "timingId", request.timingId(),
290	                        "checkpointCode", request.checkpointCode(),
291	                        "elapsedMillis", request.elapsedMillis(),
292	                        "expectedVersion", request.expectedVersion()),
293	                () -> {
294	                    // timingId 是第二层全局幂等键：同参重放原结果，异参409。
295	                    CheckpointTimingRow existingTiming =
296	                            repository.findTiming(request.timingId()).orElse(null);
297	                    if (existingTiming != null) {
298	                        return replayTimingOrConflict(raceId, bib, request, existingTiming);
299	                    }
300	
301	                    RaceRow race = requireOpenRace(raceId, request.expectedVersion());
302	                    RunnerRow runner = requireRunner(raceId, bib);
303	                    CheckpointRow checkpoint = repository
304	                            .findCheckpoint(raceId, request.checkpointCode())
305	                            .orElseThrow(() -> new NotFoundException(
306	                                    "检查点不存在: " + request.checkpointCode()));
307	                    long elapsedMillis = request.elapsedMillis();
308	                    List<CheckpointTimingRow> runnerTimings =
309	                            repository.findTimingsForRunner(raceId, bib);
310	                    String violation = CheckpointRules.validate(
311	                            runnerTimings, checkpoint.position(), elapsedMillis,
312	                            runner.finishTimeMs());
313	                    if (violation != null) {
314	                        throw new UnprocessableEntityException(violation);
315	                    }
316	                    bumpVersion(race, request.expectedVersion());
317	                    long now = clock.millis();
318	                    CheckpointTimingRow row = new CheckpointTimingRow(
319	                            request.timingId(), raceId, bib, request.checkpointCode(),
320	                            checkpoint.position(), elapsedMillis, now);
321	                    try {
322	                        repository.insertTiming(row);
323	                    } catch (DuplicateKeyException ex) {
324	                        // 并发下唯一约束兜底：同 timingId 走重放/异参冲突，其余为分段重复。
325	                        if (constraintMatches(ex, "pk_checkpoint_timing")) {
326	                            CheckpointTimingRow concurrent =
327	                                    repository.findTiming(request.timingId()).orElseThrow();
328	                            return replayTimingOrConflict(raceId, bib, request, concurrent);
329	                        }
330	                        throw new UnprocessableEntityException(
331	                                "同一选手同一检查点最多一条分段记录");
332	                    }
333	                    CheckpointTimingRow saved =
334	                            repository.findTiming(request.timingId()).orElseThrow();
335	                    return ServiceResult.created(ResponseMapper.toTimingResponse(saved));
336	                });
337	    }
