339	    private ServiceResult replayTimingOrConflict(
340	            String raceId,
341	            String bib,
342	            SubmitTimingRequest request,
343	            CheckpointTimingRow existing) {
344	        boolean sameParams = existing.raceId().equals(raceId)
345	                && existing.bib().equals(bib)
346	                && existing.checkpointCode().equals(request.checkpointCode())
347	                && existing.elapsedMillis() == request.elapsedMillis();
348	        if (!sameParams) {
349	            throw new ConflictException(
350	                    "timingId 已用于不同参数的分段记录: " + request.timingId());
351	        }
352	        return ServiceResult.created(ResponseMapper.toTimingResponse(existing));
353	    }
