355	    @Override
356	    @Transactional
357	    public ServiceResult sealRace(String raceId, SealRaceRequest request) {
358	        return withIdempotency(request.requestId(), "SEAL_RACE",
359	                orderedParams(
360	                        "raceId", raceId,
361	                        "expectedVersion", request.expectedVersion()),
362	                () -> {
363	                    RaceRow race = repository.findRaceForUpdate(raceId)
364	                            .orElseThrow(() -> new NotFoundException("赛事不存在: " + raceId));
365	                    if (race.status() == RaceStatus.SEALED) {
366	                        throw new ConflictException("赛事已封榜: " + raceId);
367	                    }
368	                    List<RunnerRow> runners = repository.findRunners(raceId);
369	                    List<PenaltyRow> penalties = repository.findPenalties(raceId);
370	                    List<CheckpointRow> checkpoints = repository.findCheckpoints(raceId);
371	                    List<CheckpointTimingRow> timings = repository.findAllTimings(raceId);
372	                    List<ResultEntry> entries =
373	                            ResultCalculator.compute(runners, penalties, checkpoints, timings);
374	
375	                    int newVersion = request.expectedVersion() + 1;
376	                    int updated = repository.sealIfOpenAtVersion(
377	                            raceId, request.expectedVersion(), newVersion);
378	                    if (updated == 0) {
379	                        throw new ConflictException("版本冲突或赛事已封榜");
380	                    }
381	                    long now = clock.millis();
382	                    List<SnapshotEntryRow> snapshotEntries = new ArrayList<>(entries.size());
383	                    for (int order = 0; order < entries.size(); order++) {
384	                        ResultEntry entry = entries.get(order);
385	                        snapshotEntries.add(new SnapshotEntryRow(
386	                                raceId,
387	                                entry.bib(),
388	                                entry.rank(),
389	                                entry.status(),
390	                                entry.finishTimeMs(),
391	                                entry.penaltyMs(),
392	                                entry.totalTimeMs(),
393	                                order,
394	                                entry.checkpointCount(),
395	                                entry.coveredCheckpointCount(),
396	                                entry.missingCheckpoints()));
397	                    }
398	                    // 在同一封榜事务内固化每名选手 × 每个检查点的明细，缺失行耗时为 null。
399	                    List<SnapshotCheckpointRow> snapshotCheckpoints =
400	                            buildSnapshotCheckpoints(raceId, runners, checkpoints, timings);
401	                    repository.insertSnapshot(new SnapshotRow(raceId, newVersion, now,
402	                            snapshotEntries, snapshotCheckpoints));
403	                    return ServiceResult.ok(new StandingResponse(
404	                            raceId, newVersion, RaceStatus.SEALED, now,
405	                            snapshotEntries.stream().map(ResponseMapper::toEntryResponse).toList()));
406	                });
407	    }
