447	    @Override
448	    @Transactional(readOnly = true)
449	    public MissingCheckpointsResponse getMissingCheckpoints(String raceId) {
450	        RaceRow race = repository.findRace(raceId)
451	                .orElseThrow(() -> new NotFoundException("赛事不存在: " + raceId));
452	        List<CheckpointRow> checkpoints = repository.findCheckpoints(raceId);
453	        List<RunnerRow> runners;
454	        List<CheckpointTimingRow> timings;
455	        if (race.status() == RaceStatus.SEALED) {
456	            SnapshotRow snapshot = repository.findSnapshot(raceId)
457	                    .orElseThrow(() -> new IllegalStateException(
458	                            "赛事已封榜但缺少快照: " + raceId));
459	            // 封榜后由固化明细派生缺失检查点，缺失行 elapsedMillis 为 null。
460	            Map<String, List<String>> missingByBib = new TreeMap<>();
461	            for (SnapshotCheckpointRow detail : snapshot.checkpoints()) {
462	                if (detail.elapsedMillis() == null) {
463	                    missingByBib.computeIfAbsent(detail.bib(), key -> new ArrayList<>())
464	                            .add(detail.checkpointCode());
465	                }
466	            }
467	            List<RunnerRow> sealedRunners = repository.findRunners(raceId);
468	            List<RunnerMissingCheckpointsResponse> rows = sealedRunners.stream()
469	                    .map(runner -> new RunnerMissingCheckpointsResponse(
470	                            runner.bib(),
471	                            missingByBib.getOrDefault(runner.bib(), List.of())))
472	                    .toList();
473	            return new MissingCheckpointsResponse(
474	                    raceId, race.version(), checkpoints.size(), rows);
475	        }
476	        runners = repository.findRunners(raceId);
477	        timings = repository.findAllTimings(raceId);
478	        // 按参赛号字典序稳定汇总；缺失=已配置但该选手尚无分段记录的检查点。
479	        Map<String, java.util.Set<String>> coveredByBib = new TreeMap<>();
480	        for (RunnerRow runner : runners) {
481	            coveredByBib.put(runner.bib(), new java.util.HashSet<>());
482	        }
483	        for (CheckpointTimingRow timing : timings) {
484	            java.util.Set<String> covered = coveredByBib.get(timing.bib());
485	            if (covered != null) {
486	                covered.add(timing.checkpointCode());
487	            }
488	        }
489	        List<RunnerMissingCheckpointsResponse> rows = coveredByBib.entrySet().stream()
490	                .map(entry -> new RunnerMissingCheckpointsResponse(
491	                        entry.getKey(),
492	                        checkpoints.stream()
493	                                .map(CheckpointRow::checkpointCode)
494	                                .filter(code -> !entry.getValue().contains(code))
495	                                .toList()))
496	                .toList();
497	        return new MissingCheckpointsResponse(
498	                raceId, race.version(), checkpoints.size(), rows);
499	    }
