511	    /**
512	     * 幂等包装：同键同参重放原成功结果，同键异参409；
513	     * 业务异常随事务回滚，占位行消失，不占用 requestId。
514	     */
515	    private ServiceResult withIdempotency(
516	            String requestId,
517	            String operation,
518	            TreeMap<String, Object> params,
519	            Supplier<ServiceResult> action) {
520	        String digest = digest(operation, params);
521	        long deadline = clock.millis() + INFLIGHT_WAIT_MAX_MS;
522	        boolean acquired = false;
523	        while (!acquired) {
524	            try {
525	                repository.insertIdempotencyPlaceholder(
526	                        requestId, operation, digest, clock.millis());
527	                acquired = true;
528	            } catch (DuplicateKeyException ex) {
529	                Optional<IdempotencyRow> existing =
530	                        repository.findIdempotencyForUpdate(requestId);
531	                if (existing.isEmpty()) {
532	                    // 先行者事务回滚，占位行已随其消失，立即重新占位。
533	                    continue;
534	                }
535	                IdempotencyRow row = existing.get();
536	                if (row.responseStatus() == 0) {
537	                    // 理论上不会出现（提交必带最终响应）；防御性等待先行者完成。
538	                    if (clock.millis() >= deadline) {
539	                        throw new ConflictException("相同 requestId 的请求仍在处理中");
540	                    }
541	                    sleepBriefly();
542	                    continue;
543	                }
544	                if (!row.requestDigest().equals(digest)) {
545	                    throw new ConflictException(
546	                            "requestId 已用于不同参数的请求: " + requestId);
547	                }
548	                JsonNode replayedBody = parseReplayedBody(row.responseBody());
549	                return new ServiceResult(replayedBody, row.responseStatus());
550	            }
551	        }
552	        ServiceResult result = action.get();
553	        repository.completeIdempotency(
554	                requestId, result.status(), writeJson(result.body()));
555	        return result;
556	    }
557	
558	    private RaceRow requireOpenRace(String raceId, Integer expectedVersion) {
559	        // 先取 race 行写锁并持有到事务结束：本事务随后读到的选手/处罚/分段数据
560	        // 必然处于某个已串行化的赛事版本上，不会与并发写者的已提交明细交错。
561	        RaceRow race = repository.findRaceForUpdate(raceId)
562	                .orElseThrow(() -> new NotFoundException("赛事不存在: " + raceId));
563	        if (race.status() == RaceStatus.SEALED) {
564	            throw new ConflictException("赛事已封榜，禁止写入: " + raceId);
565	        }
566	        if (race.version() != expectedVersion) {
567	            throw new ConflictException("版本冲突: expected=" + expectedVersion
568	                    + ", actual=" + race.version());
569	        }
570	        return race;
571	    }
572	
573	    private void bumpVersion(RaceRow race, int expectedVersion) {
574	        int updated = repository.bumpVersionIfOpen(race.raceId(), expectedVersion);
575	        if (updated == 0) {
576	            // 行锁释放后发现赛事已封榜或版本已被推进。
577	            RaceRow refreshed = repository.findRace(race.raceId()).orElseThrow();
578	            if (refreshed.status() == RaceStatus.SEALED) {
579	                throw new ConflictException("赛事已封榜，禁止写入: " + race.raceId());
580	            }
581	            throw new ConflictException("版本冲突: expected=" + expectedVersion
582	                    + ", actual=" + refreshed.version());
583	        }
584	    }
