591	    private static void validateFinishTime(Long finishTimeMs, boolean nullable) {
592	        if (finishTimeMs == null) {
593	            if (!nullable) {
594	                throw new BadRequestException("修订计时必须携带 finishTimeMs");
595	            }
596	            return;
597	        }
598	        if (finishTimeMs < 1 || finishTimeMs > MAX_FINISH_TIME_MS) {
599	            throw new BadRequestException("完赛耗时毫秒数必须在 1~86400000 之间");
600	        }
601	    }
602	
603	    private static PenaltyType parsePenaltyType(String type) {
604	        try {
605	            return PenaltyType.valueOf(type);
606	        } catch (IllegalArgumentException ex) {
607	            throw new BadRequestException("未知处罚类型: " + type);
608	        }
609	    }
610	
611	    private static TreeMap<String, Object> orderedParams(Object... keyValues) {
612	        if (keyValues.length % 2 != 0) {
613	            throw new IllegalArgumentException("参数必须为键值对");
614	        }
615	        TreeMap<String, Object> params = new TreeMap<>();
616	        for (int i = 0; i < keyValues.length; i += 2) {
617	            params.put((String) keyValues[i], keyValues[i + 1]);
618	        }
619	        return params;
620	    }
621	
622	    private String digest(String operation, Map<String, Object> params) {
623	        try {
624	            Map<String, Object> canonical = new TreeMap<>(params);
625	            canonical.put("__operation", operation);
626	            MessageDigest messageDigest = MessageDigest.getInstance("SHA-256");
627	            byte[] bytes = objectMapper.writerWithDefaultPrettyPrinter()
628	                    .writeValueAsString(canonical)
629	                    .getBytes(StandardCharsets.UTF_8);
630	            return HexFormat.of().formatHex(messageDigest.digest(bytes));
631	        } catch (NoSuchAlgorithmException | com.fasterxml.jackson.core.JsonProcessingException ex) {
632	            throw new IllegalStateException("计算请求摘要失败", ex);
633	        }
634	    }
635	
636	    private String writeJson(Object body) {
637	        try {
638	            return objectMapper.writeValueAsString(body);
639	        } catch (com.fasterxml.jackson.core.JsonProcessingException ex) {
640	            throw new IllegalStateException("序列化响应失败", ex);
641	        }
642	    }
643	
644	    private JsonNode parseReplayedBody(String body) {
645	        try {
646	            return objectMapper.readTree(body);
647	        } catch (com.fasterxml.jackson.core.JsonProcessingException ex) {
648	            throw new IllegalStateException("解析原响应失败", ex);
649	        }
650	    }
651	
652	    private static void sleepBriefly() {
653	        try {
654	            Thread.sleep(10L);
655	        } catch (InterruptedException ex) {
656	            Thread.currentThread().interrupt();
657	            throw new ConflictException("等待同键请求完成时被中断");
658	        }
659	    }
660	
661	    /**
662	     * 校验检查点配置请求体：1~20个、代码非空且赛事内唯一、position 从1连续递增（无重复无缺口）。
663	     */
664	    private static void validateCheckpointDefinitions(
665	            List<ConfigureCheckpointsRequest.CheckpointDefinition> definitions) {
666	        if (definitions.isEmpty() || definitions.size() > 20) {
667	            throw new BadRequestException("检查点数量必须在 1~20 之间");
668	        }
669	        java.util.Set<String> codes = new java.util.HashSet<>();
670	        java.util.Set<Integer> positions = new java.util.HashSet<>();
671	        for (ConfigureCheckpointsRequest.CheckpointDefinition def : definitions) {
672	            if (!codes.add(def.checkpointCode())) {
673	                throw new BadRequestException("检查点代码在赛事内重复: " + def.checkpointCode());
674	            }
675	            positions.add(def.position());
676	        }
677	        for (int expected = 1; expected <= definitions.size(); expected++) {
678	            if (!positions.contains(expected)) {
679	                throw new BadRequestException(
680	                        "检查点顺序必须从1连续递增，缺少 position=" + expected);
681	            }
682	        }
683	    }
684	
685	    /**
686	     * 构造封榜快照的全部分段明细：每名选手 × 每个检查点一行，
687	     * 已有通过记录固化耗时与 timingId，缺失检查点对应字段为 null；顺序为参赛号、检查点顺序。
688	     */
689	    private List<SnapshotCheckpointRow> buildSnapshotCheckpoints(
690	            String raceId,
691	            List<RunnerRow> runners,
692	            List<CheckpointRow> checkpoints,
693	            List<CheckpointTimingRow> timings) {
694	        Map<String, Map<String, CheckpointTimingRow>> byBibAndCode = new TreeMap<>();
695	        for (CheckpointTimingRow timing : timings) {
696	            byBibAndCode
697	                    .computeIfAbsent(timing.bib(), key -> new TreeMap<>())
698	                    .put(timing.checkpointCode(), timing);
699	        }
700	        List<SnapshotCheckpointRow> rows = new ArrayList<>();
701	        // runners 已按参赛号字典序返回，保证无分段记录的选手也被完整固化为“全部缺失”。
702	        for (RunnerRow runner : runners) {
703	            appendSnapshotCheckpointRows(
704	                    rows, raceId, runner.bib(), checkpoints,
705	                    byBibAndCode.getOrDefault(runner.bib(), Map.of()));
706	        }
707	        return rows;
708	    }
709	
710	    private void appendSnapshotCheckpointRows(
711	            List<SnapshotCheckpointRow> rows,
712	            String raceId,
713	            String bib,
714	            List<CheckpointRow> checkpoints,
715	            Map<String, CheckpointTimingRow> timingByCode) {
716	        for (CheckpointRow checkpoint : checkpoints) {
717	            CheckpointTimingRow timing = timingByCode.get(checkpoint.checkpointCode());
718	            if (timing == null) {
719	                rows.add(new SnapshotCheckpointRow(
720	                        raceId, bib, checkpoint.checkpointCode(),
721	                        checkpoint.position(), null, null));
722	            } else {
723	                rows.add(new SnapshotCheckpointRow(
724	                        raceId, bib, checkpoint.checkpointCode(),
725	                        checkpoint.position(), timing.elapsedMillis(), timing.timingId()));
726	            }
727	        }
728	    }
729	
730	    /** 判断唯一约束异常是否源自指定约束（H2 异常信息中的约束名可能为大写）。 */
731	    private static boolean constraintMatches(DuplicateKeyException ex, String constraintName) {
732	        Throwable cause = ex.getMostSpecificCause();
733	        String message = cause.getMessage();
734	        return message != null
735	                && message.toUpperCase(java.util.Locale.ROOT).contains(constraintName.toUpperCase(java.util.Locale.ROOT));
736	    }
737	}
